-- Source: database/functions/others/configuration_settings.sql
-- Narrow authoring intent, shared by UI and MCP. Never a caller-selected JSON path.
CREATE OR REPLACE FUNCTION public.validate_configuration_value_internal_v1(value jsonb, rule jsonb)
RETURNS void LANGUAGE plpgsql SET search_path=public,extensions AS $$
DECLARE k text; item jsonb; kind text:=rule->>'type';
BEGIN
 IF value='null'::jsonb AND COALESCE((rule->>'nullable')::boolean,false) THEN RETURN; END IF;
 IF kind IN ('string','datetime','email','timezone') THEN
  IF jsonb_typeof(value)<>'string' OR length(value#>>'{}')>COALESCE((rule->>'maxLength')::int,8192) THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid settings text'; END IF;
  IF kind='email' AND (value#>>'{}') !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid Reply-To'; END IF;
  IF kind='timezone' AND NOT EXISTS(SELECT FROM pg_timezone_names WHERE name=value#>>'{}') THEN
   RAISE invalid_parameter_value USING MESSAGE='unknown timezone'; END IF;
  IF kind='datetime' THEN
   IF (value#>>'{}') !~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN RAISE invalid_parameter_value USING MESSAGE='explicit timestamp offset required'; END IF;
   PERFORM (value#>>'{}')::timestamptz;
  END IF;
 ELSIF kind IN ('integer','number') THEN
  IF jsonb_typeof(value)<>'number' THEN RAISE invalid_parameter_value USING MESSAGE='invalid settings number'; END IF;
  IF (kind='integer' AND (value#>>'{}')::numeric<>trunc((value#>>'{}')::numeric))
   OR (rule ? 'minimum' AND (value#>>'{}')::numeric<(rule->>'minimum')::numeric)
   OR (rule ? 'maximum' AND (value#>>'{}')::numeric>(rule->>'maximum')::numeric) THEN
   RAISE invalid_parameter_value USING MESSAGE='settings number out of range'; END IF;
 ELSIF kind='boolean' THEN
  IF jsonb_typeof(value)<>'boolean' THEN RAISE invalid_parameter_value USING MESSAGE='invalid settings boolean'; END IF;
 ELSIF kind='object' THEN
  IF jsonb_typeof(value)<>'object' THEN RAISE invalid_parameter_value USING MESSAGE='invalid settings object'; END IF;
  IF EXISTS(SELECT FROM jsonb_array_elements_text(COALESCE(rule->'required','[]')) AS required_keys(required_key) WHERE NOT value ? required_key) THEN
   RAISE invalid_parameter_value USING MESSAGE='incomplete settings object'; END IF;
  FOR k,item IN SELECT * FROM jsonb_each(value) LOOP
   IF NOT (rule->'properties' ? k) THEN RAISE invalid_parameter_value USING MESSAGE='unsupported settings field'; END IF;
   PERFORM public.validate_configuration_value_internal_v1(item,rule->'properties'->k);
  END LOOP;
 ELSIF kind='array' THEN
  IF jsonb_typeof(value)<>'array' OR jsonb_array_length(value)>COALESCE((rule->>'maxItems')::int,100) THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid settings array'; END IF;
  FOR item IN SELECT * FROM jsonb_array_elements(value) LOOP
   PERFORM public.validate_configuration_value_internal_v1(item,rule->'items');
  END LOOP;
 ELSE RAISE invalid_parameter_value USING MESSAGE='unsupported settings type'; END IF;
 IF rule ? 'enum' AND NOT (rule->'enum' @> jsonb_build_array(value)) THEN RAISE invalid_parameter_value USING MESSAGE='invalid settings choice'; END IF;
 IF rule ? 'pattern' AND (value#>>'{}') !~ (rule->>'pattern') THEN RAISE invalid_parameter_value USING MESSAGE='invalid settings format'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.validate_configuration_value_internal_v1(jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.merge_configuration_settings_internal_v1(current_data jsonb, settings jsonb, scope text)
RETURNS jsonb LANGUAGE plpgsql SET search_path=public,extensions AS $$
DECLARE k text; value jsonb; result jsonb:=COALESCE(NULLIF(current_data,'null'::jsonb),'{}');
BEGIN
 PERFORM public.validate_configuration_value_internal_v1(settings,jsonb_build_object('type','object','properties',public.configuration_settings_contract_internal_v1()->scope));
 FOR k,value IN SELECT * FROM jsonb_each(settings) LOOP
  result:=CASE WHEN value='null'::jsonb THEN result-k ELSE jsonb_set(result,ARRAY[k],value,true) END;
 END LOOP;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.merge_configuration_settings_internal_v1(jsonb,jsonb,text) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION public.apply_occasion_settings_intent_internal_v1(p_occasion bigint, intent jsonb)
RETURNS jsonb LANGUAGE plpgsql SET search_path=public,extensions AS $$
DECLARE current_row public.occasions%ROWTYPE; result jsonb:=intent; f jsonb; old_f jsonb;
 features jsonb; patch jsonb; code text; k text; rule jsonb; supported boolean;
 spec jsonb:=public.configuration_settings_contract_internal_v1();
BEGIN
 SELECT * INTO STRICT current_row FROM public.occasions WHERE id=p_occasion;
 SELECT COALESCE((data->>'IS_APP_SUPPORTED')::boolean,false) INTO supported FROM public.organizations WHERE id=current_row.organization;
 IF intent ? 'settings' THEN
  IF intent ? 'data' THEN RAISE invalid_parameter_value USING MESSAGE='choose settings intent or legacy data'; END IF;
  result:=(result-'settings')||jsonb_build_object('data',public.merge_configuration_settings_internal_v1(current_row.data,intent->'settings','occasion'));
 ELSIF intent ? 'data' THEN
  -- Released full-snapshot clients retain their boundary; known fields share validation.
  IF jsonb_typeof(intent->'data')<>'object' THEN RAISE invalid_parameter_value USING MESSAGE='invalid occasion metadata'; END IF;
  FOR k,rule IN SELECT * FROM jsonb_each(spec->'occasion') LOOP
   IF intent->'data' ? k THEN PERFORM public.validate_configuration_value_internal_v1(intent->'data'->k,rule); END IF;
  END LOOP;
 END IF;
 IF result#>>'{data,image}' IS DISTINCT FROM current_row.data->>'image' AND result#>>'{data,image}' IS NOT NULL
  AND NOT EXISTS(SELECT FROM public.images WHERE link=result#>>'{data,image}' AND (occasion=p_occasion OR unit=current_row.unit)) THEN
  RAISE invalid_parameter_value USING MESSAGE='image must belong to the occasion or its organizer'; END IF;
 IF result ? 'data' THEN result:=jsonb_set(result,'{data}',jsonb_set(result->'data','{client_sync_v1}',COALESCE(current_row.data->'client_sync_v1','false'),true)); END IF;
 IF intent ? 'feature_changes' THEN
  IF intent ? 'features' OR jsonb_typeof(intent->'feature_changes')<>'array' OR jsonb_array_length(intent->'feature_changes')>25 THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid feature settings intent'; END IF;
  features:=COALESCE(current_row.features,'[]');
  IF (SELECT count(*)<>count(DISTINCT x->>'code') FROM jsonb_array_elements(intent->'feature_changes') x) THEN
   RAISE invalid_parameter_value USING MESSAGE='duplicate feature'; END IF;
  FOR patch IN SELECT * FROM jsonb_array_elements(intent->'feature_changes') LOOP
   code:=patch->>'code';
   IF NOT (spec->'features' ? code) THEN RAISE invalid_parameter_value USING MESSAGE='unsupported feature'; END IF;
   PERFORM public.validate_configuration_value_internal_v1(patch-'code',jsonb_build_object('type','object','properties',spec->'features'->code));
   SELECT value INTO old_f FROM jsonb_array_elements(features) WHERE value->>'code'=code;
   f:=COALESCE(old_f,jsonb_build_object('code',code,'is_enabled',false))||patch;
   SELECT COALESCE(jsonb_agg(value),'[]') INTO features FROM jsonb_array_elements(features) WHERE value->>'code'<>code;
   features:=features||jsonb_build_array(f);
  END LOOP;
  result:=(result-'feature_changes')||jsonb_build_object('features',features);
 ELSIF NOT (intent ? 'features') THEN
  result:=result||jsonb_build_object('features',COALESCE(current_row.features,'[]'));
 END IF;
 -- Validate shared known settings on both current intent and released snapshots.
 IF jsonb_typeof(result->'features')<>'array' THEN RAISE invalid_parameter_value USING MESSAGE='invalid features'; END IF;
 FOR f IN SELECT * FROM jsonb_array_elements(result->'features') LOOP
  code:=f->>'code';
  SELECT value INTO old_f FROM jsonb_array_elements(COALESCE(current_row.features,'[]')) WHERE value->>'code'=code;
  IF f IS DISTINCT FROM old_f AND spec->'features' ? code THEN
   IF code='map' THEN
    FOR patch IN SELECT * FROM jsonb_array_elements(jsonb_build_array(f->'map_layer',f->'map_layer_offline')) LOOP
     IF COALESCE((patch->>'forceOfflineMap')::boolean,false) AND NULLIF(btrim(patch->>'offlineMapBundleManifestURL'),'') IS NULL THEN
      RAISE invalid_parameter_value USING MESSAGE='MapLibre requires a bundle manifest'; END IF;
    END LOOP;
   END IF;
   FOR k,rule IN SELECT * FROM jsonb_each(spec->'features'->code) LOOP
    IF f ? k THEN PERFORM public.validate_configuration_value_internal_v1(f->k,rule); END IF;
   END LOOP;
  END IF;
  IF code='program_notifications' AND COALESCE((f->>'is_enabled')::boolean,false) THEN RAISE invalid_parameter_value USING MESSAGE='program notifications delivery is not implemented'; END IF;
  IF NOT supported AND spec->'appOnly' ? code AND COALESCE((f->>'is_enabled')::boolean,false)
   AND NOT COALESCE((old_f->>'is_enabled')::boolean,false) THEN RAISE invalid_parameter_value USING MESSAGE='feature requires app-supported tenant'; END IF;
  IF NOT supported AND code='form' AND NOT COALESCE((f->>'is_enabled')::boolean,false) THEN
   RAISE invalid_parameter_value USING MESSAGE='form is required for this tenant'; END IF;
 END LOOP;
 IF intent ? 'title' AND intent->'title'<>'null'::jsonb AND (jsonb_typeof(intent->'title')<>'string' OR nullif(btrim(intent->>'title'),'') IS NULL OR length(intent->>'title')>512) THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid occasion title'; END IF;
 IF COALESCE((intent->>'start_time')::timestamptz,current_row.start_time)>COALESCE((intent->>'end_time')::timestamptz,current_row.end_time) THEN
  RAISE invalid_parameter_value USING MESSAGE='occasion start must precede end'; END IF;
 IF COALESCE((intent->>'is_promoted')::boolean,current_row.is_promoted) AND NULLIF(COALESCE(result->'data',current_row.data)->>'image','') IS NULL THEN
  RAISE invalid_parameter_value USING MESSAGE='promotion requires an occasion image'; END IF;
 IF COALESCE((current_row.data->>'client_sync_v1')::boolean,false) AND NOT current_row.is_hidden AND COALESCE((intent->>'is_hidden')::boolean,false) THEN
  RAISE object_not_in_prerequisite_state USING MESSAGE='disable client_sync_v1 before hiding occasion'; END IF;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.apply_occasion_settings_intent_internal_v1(bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;


-- Source: database/functions/user_permissions/game_settings.sql
CREATE OR REPLACE FUNCTION public.can_edit_game_settings(p_occasion bigint) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT auth.uid() IS NOT NULL AND public.get_is_editor_on_occasion(p_occasion)
 AND EXISTS(SELECT FROM public.occasions o JOIN public.user_info ui ON ui.id=auth.uid() AND ui.organization=o.organization WHERE o.id=p_occasion);
$$;
REVOKE ALL ON FUNCTION public.can_edit_game_settings(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_edit_game_settings(bigint) TO authenticated,service_role;


-- Source: database/functions/others/save_occasion_domain_command_internal_v1.sql

-- The public save wrapper and the settings UI allow unit editors. The renamed
-- canonical domain command retained its older occasion-only guard, so it must
-- accept the same role before it reaches update_occasion_internal_v1.
CREATE OR REPLACE FUNCTION public.save_occasion_domain_command_internal_v1(
  p_occasion bigint,
  p_command_id uuid,
  p_expected_version bigint,
  p_config jsonb
) RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_version bigint;
  v_begin jsonb;
  v_hash text;
  v_entity jsonb;
  v_old_hidden boolean;
  v_new_hidden boolean;
  v_old_unit bigint;
  v_new_unit bigint;
  v_features jsonb;
  v_fanout_units bigint[] := '{}';
BEGIN
  SELECT o.unit INTO v_old_unit
  FROM public.occasions o
  WHERE o.id = p_occasion;

  IF v_actor IS NULL OR NOT public.can_edit_occasion(p_occasion,(p_config->>'unit')::bigint) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor required';
  END IF;

  IF p_config IS NULL OR jsonb_typeof(p_config) <> 'object'
    OR octet_length(p_config::text) > 1048576
    OR (p_config->>'id')::bigint IS DISTINCT FROM p_occasion
    OR EXISTS (
      SELECT 1
      FROM jsonb_object_keys(p_config) key
      WHERE key NOT IN (
        'id', 'start_time', 'end_time', 'is_open', 'is_hidden', 'is_promoted',
        'link', 'title', 'description', 'data', 'services', 'organization',
        'unit', 'features', 'settings', 'feature_changes', 'form_link', 'has_orders', 'stats', 'ticket_layout_change'
      )
    )
  THEN
    RAISE invalid_parameter_value USING MESSAGE = 'invalid occasion aggregate';
  END IF;

  v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion', p_occasion,
    'expectedVersion', p_expected_version,
    'config', p_config
  )::text, 'UTF8'), 'sha256'), 'hex');
  v_begin := public.begin_client_mutation_v1(
    p_command_id,
    'occasion.config.save',
    p_occasion,
    v_actor,
    v_hash
  );
  IF v_begin->>'disposition' = 'replay' THEN
    RETURN v_begin->'response';
  END IF;

  PERFORM public.notification_center_initialized_internal((SELECT organization FROM public.occasions WHERE id=p_occasion));
  IF NOT (p_config ? 'ticket_layout_change' AND p_config-ARRAY['id','ticket_layout_change']='{}'::jsonb) THEN
    PERFORM 1 FROM public.forms WHERE occasion=p_occasion ORDER BY id FOR UPDATE;
  END IF;

  SELECT o.is_hidden, o.unit INTO v_old_hidden, v_old_unit
  FROM public.occasions o
  WHERE o.id = p_occasion
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,
      'rejected',
      404,
      jsonb_build_object('version', 0, 'occasion', NULL)
    );
  END IF;

  INSERT INTO public.client_aggregate_versions(
    aggregate_type, scope_type, scope_id, aggregate_id, version
  ) VALUES ('occasion', 'occasion', p_occasion, p_occasion::text, 0)
  ON CONFLICT DO NOTHING;
  SELECT version INTO v_version
  FROM public.client_aggregate_versions
  WHERE aggregate_type = 'occasion'
    AND scope_type = 'occasion'
    AND scope_id = p_occasion
    AND aggregate_id = p_occasion::text
  FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    SELECT to_jsonb(o) || jsonb_build_object('aggregate_version', v_version)
    INTO v_entity
    FROM public.occasions o
    WHERE o.id = p_occasion;
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,
      'conflict',
      409,
      jsonb_build_object('version', v_version, 'occasion', v_entity)
    );
  END IF;

  IF p_config ? 'ticket_layout_change' AND p_config - ARRAY['id','ticket_layout_change']='{}'::jsonb THEN
    IF NOT public.can_edit_ticket_layout(p_occasion) THEN
      RAISE insufficient_privilege USING MESSAGE='unit editor required';
    END IF;
    SELECT features INTO v_features FROM public.occasions WHERE id=p_occasion;
    v_features:=public.merge_ticket_layout_features(v_features,v_features,p_config->'ticket_layout_change');
    v_features:=public.merge_ticket_appearance_internal_v1(p_occasion,v_features,p_config#>'{ticket_layout_change,appearance}');
    PERFORM public.validate_ticket_layout_references(p_occasion,f->'layout')
      FROM jsonb_array_elements(v_features) f WHERE f->>'code'='ticket' AND f ? 'layout';
    UPDATE public.occasions SET features=v_features,updated_at=clock_timestamp() WHERE id=p_occasion;
  ELSE
    PERFORM public.update_occasion_internal_v1(
      public.apply_occasion_settings_intent_internal_v1(p_occasion,p_config));
  END IF;
  UPDATE public.client_aggregate_versions
  SET version = version + 1, updated_at = clock_timestamp()
  WHERE aggregate_type = 'occasion'
    AND scope_type = 'occasion'
    AND scope_id = p_occasion
    AND aggregate_id = p_occasion::text
  RETURNING version INTO v_version;
  SELECT to_jsonb(o) || jsonb_build_object('aggregate_version', v_version)
  INTO v_entity
  FROM public.occasions o
  WHERE o.id = p_occasion;

  v_new_hidden := (v_entity->>'is_hidden')::boolean;
  v_new_unit := (v_entity->>'unit')::bigint;
  IF NOT v_old_hidden THEN
    v_fanout_units := array_append(v_fanout_units, v_old_unit);
  END IF;
  IF NOT v_new_hidden AND v_new_unit IS DISTINCT FROM v_old_unit THEN
    v_fanout_units := array_append(v_fanout_units, v_new_unit);
  ELSIF NOT v_new_hidden AND v_old_hidden THEN
    v_fanout_units := array_append(v_fanout_units, v_new_unit);
  END IF;

  RETURN public.complete_client_mutation_applied_v1(
    p_command_id,
    p_occasion,
    'occasion.config.save',
    'configuration',
    jsonb_build_array(jsonb_build_object(
      'entityType', 'occasion',
      'entityId', p_occasion,
      'operation', 'update',
      'safeLabel', left(v_entity->>'title', 240),
      'changedFields', jsonb_build_array('configuration')
    )),
    CASE WHEN v_old_hidden AND NOT v_new_hidden THEN ARRAY[
      'occasion_config', 'program_catalog', 'map_catalog', 'content_catalog',
      'live_public'
    ] ELSE ARRAY['occasion_config'] END,
    '[]',
    '[]',
    jsonb_build_object('version', v_version, 'occasion', v_entity),
    CASE WHEN NOT v_new_hidden THEN ARRAY['occasion_config'] ELSE '{}'::text[] END,
    '[]',
    'user',
    NULL,
    '[]',
    v_fanout_units
  );
END;
$$;

REVOKE ALL ON FUNCTION public.save_occasion_domain_command_internal_v1(
  bigint, uuid, bigint, jsonb
) FROM PUBLIC, anon, authenticated;



-- Source: database/functions/others/save_occasion_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_occasion_client_sync_v1(p_occasion bigint,p_command_id uuid,p_expected_version bigint,p_config jsonb)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE config jsonb:=p_config; enabled jsonb;
BEGIN
 IF p_config ? 'data' AND jsonb_typeof(p_config->'data')='object' THEN
  SELECT COALESCE(data->'client_sync_v1','false') INTO enabled FROM public.occasions WHERE id=p_occasion;
  config:=jsonb_set(p_config,'{data}',jsonb_set(p_config->'data','{client_sync_v1}',COALESCE(enabled,'false'),true));
 END IF;
 RETURN public.save_occasion_domain_command_internal_v1(p_occasion,p_command_id,p_expected_version,config);
END $$;
REVOKE ALL ON FUNCTION public.save_occasion_client_sync_v1(bigint,uuid,bigint,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_occasion_client_sync_v1(bigint,uuid,bigint,jsonb) TO authenticated;


-- Source: database/functions/units/update_unit_internal_v1.sql
CREATE OR REPLACE FUNCTION public.update_unit_internal_v1(p_unit_id bigint, p_title text, p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
    IF length(p_title) > 30 THEN
        RAISE EXCEPTION 'Unit title cannot exceed 30 characters';
    END IF;

    -- Check if the current user is a manager for the provided unit
    IF NOT public.can_manage_unit_configuration(p_unit_id) THEN
        RAISE EXCEPTION 'User is not a manager on this unit';
    END IF;

    -- Update the unit
    UPDATE units
    SET
        title = p_title,
        data = p_data
    WHERE id = p_unit_id;
END;
$function$
;
REVOKE ALL ON FUNCTION public.update_unit_internal_v1(p_unit_id bigint, p_title text, p_data jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.update_unit_internal_v1(bigint,text,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.update_unit_internal_v1(bigint,text,jsonb) TO service_role;


-- Source: database/functions/units/save_unit_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_unit_client_sync_v1(p_unit bigint, p_command_id uuid, p_expected_version bigint, p_unit_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_version bigint;
  v_before jsonb; v_after jsonb; v_commit public.client_commits%ROWTYPE;
BEGIN
  IF v_actor IS NULL OR NOT public.can_manage_unit_configuration(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  IF p_unit_data IS NULL OR jsonb_typeof(p_unit_data)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_unit_data) key
      WHERE key NOT IN ('id','title','data','settings'))
    OR (p_unit_data->>'id')::bigint IS DISTINCT FROM p_unit
    OR (p_unit_data ? 'title' AND (nullif(btrim(p_unit_data->>'title'),'') IS NULL OR length(p_unit_data->>'title')>30))
    OR (p_unit_data ? 'settings' AND p_unit_data ? 'data')
    OR jsonb_typeof(COALESCE(p_unit_data->'data','{}'::jsonb))<>'object'
    OR octet_length(p_unit_data::text)>262144 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid unit aggregate'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'unit',p_unit,'expectedVersion',p_expected_version,
    'data',p_unit_data)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,'unit.config.save',
    p_unit,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT jsonb_build_object('id',u.id,'title',u.title,'data',u.data)
    INTO v_before FROM public.units u WHERE u.id=p_unit FOR UPDATE;
  IF v_before IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'rejected',404,jsonb_build_object('version',0,'unit',NULL)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('unit','unit',p_unit,p_unit::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='unit' AND scope_type='unit'
      AND scope_id=p_unit AND aggregate_id=p_unit::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'unit',v_before||
        jsonb_build_object('aggregate_version',v_version))); END IF;
  v_after:=jsonb_build_object('id',p_unit,'title',COALESCE(p_unit_data->>'title',v_before->>'title'),
    'data',CASE WHEN p_unit_data ? 'settings' THEN public.merge_configuration_settings_internal_v1(v_before->'data',p_unit_data->'settings','unit')
      ELSE COALESCE(p_unit_data->'data',v_before->'data','{}'::jsonb) END);
  PERFORM public.merge_configuration_settings_internal_v1('{}',
    (SELECT COALESCE(jsonb_object_agg(key,value),'{}') FROM jsonb_each(v_after->'data') WHERE public.configuration_settings_contract_internal_v1()->'unit' ? key),'unit');
  IF v_before=v_after THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',v_version,
      'unit',v_before||jsonb_build_object('aggregate_version',v_version))); END IF;
  PERFORM public.update_unit_internal_v1(
    p_unit,v_after->>'title',v_after->'data');
  UPDATE public.client_aggregate_versions SET version=version+1,
    updated_at=clock_timestamp() WHERE aggregate_type='unit' AND scope_type='unit'
    AND scope_id=p_unit AND aggregate_id=p_unit::text RETURNING version INTO v_version;
  INSERT INTO public.client_commits
    (unit,actor_id,actor_display,actor_kind,source,change_class)
  SELECT p_unit,v_actor,nullif(concat_ws(' ',ui.name,ui.surname),''),'user',
    'unit.config.save','configuration' FROM public.user_info ui WHERE ui.id=v_actor
  RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'unit',p_unit::text,'update',
    left(v_after->>'title',240),ARRAY['configuration']);
  PERFORM public.fanout_unit_catalog_v1(v_commit.commit_id,p_unit);
  RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object(
    'status','applied','code',200,'data',jsonb_build_object('version',v_version,
      'unit',v_after||jsonb_build_object('aggregate_version',v_version)),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit.commit_id,'replayed',false,'occurredAt',v_commit.occurred_at),
    'sync',jsonb_build_object('replacements','[]'::jsonb)),v_commit.commit_id);
END; $function$
;
REVOKE ALL ON FUNCTION public.save_unit_client_sync_v1(p_unit bigint, p_command_id uuid, p_expected_version bigint, p_unit_data jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_unit_client_sync_v1(p_unit bigint, p_command_id uuid, p_expected_version bigint, p_unit_data jsonb) TO authenticated;
REVOKE ALL ON FUNCTION public.save_unit_client_sync_v1(bigint,uuid,bigint,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.save_unit_client_sync_v1(bigint,uuid,bigint,jsonb) TO authenticated,service_role;


-- Source: database/functions/others/game_update_settings.sql
CREATE OR REPLACE FUNCTION public.game_update_settings_internal_v1(oc bigint, new_start_time timestamp with time zone, new_end_time timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  existing_data JSONB;
  updated_game_data JSONB;
BEGIN
  -- Check if the user is an editor on the occasion
  IF (SELECT public.can_edit_game_settings(oc)) <> TRUE THEN
    RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion');
  END IF;

  IF new_start_time>new_end_time THEN RAISE invalid_parameter_value USING MESSAGE='game start must precede end'; END IF;

  -- Retrieve existing data JSON if any
  SELECT data INTO existing_data FROM public.occasions WHERE id = oc;

  -- Create or update the "game" object with new start and end times, preserving other keys in "game"
  updated_game_data := COALESCE(existing_data->'game', '{}'::jsonb) || jsonb_build_object(
    'start', CASE WHEN new_start_time IS NOT NULL THEN to_jsonb(new_start_time) ELSE 'null'::jsonb END,
    'end', CASE WHEN new_end_time IS NOT NULL THEN to_jsonb(new_end_time) ELSE 'null'::jsonb END
  );

  -- Update the data JSON with the updated "game" data
  UPDATE public.occasions
  SET data = jsonb_set(
      COALESCE(data, '{}'::jsonb),                          -- Ensure data is an empty JSON if NULL
      ARRAY['game'],                                        -- Path to the "game" key
      updated_game_data,                                    -- Updated game data with merged start and end times
      true
    )
  WHERE id = oc;

  -- Return success response
  RETURN jsonb_build_object(
    'code', 200,
    'message', 'Game settings updated successfully'
  );
END;
$function$
;
REVOKE ALL ON FUNCTION public.game_update_settings_internal_v1(bigint,timestamptz,timestamptz) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.game_update_settings(oc bigint, new_start_time timestamp with time zone, new_end_time timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path=public,extensions
AS $function$
BEGIN RETURN public.game_update_settings_client_sync_v1(
  oc,new_start_time,new_end_time,extensions.gen_random_uuid())->'data'; END; $function$
;
REVOKE ALL ON FUNCTION public.game_update_settings(bigint,timestamptz,timestamptz) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.game_update_settings(bigint,timestamptz,timestamptz) TO authenticated;


-- Source: database/functions/others/game_update_settings_client_sync_v1.sql
CREATE OR REPLACE FUNCTION public.save_game_settings_command_internal_v1(p_occasion bigint, p_start timestamp with time zone, p_end timestamp with time zone, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_before jsonb; v_after jsonb; v_version bigint;
BEGIN
  IF v_actor IS NULL OR NOT public.can_edit_game_settings(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to((jsonb_build_object(
    'occasion',p_occasion,'start',p_start,'end',p_end)||CASE WHEN p_expected_version IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('expectedVersion',p_expected_version) END)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'occasion.game.settings',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT o.data INTO v_before FROM public.occasions o
    WHERE o.id=p_occasion FOR UPDATE;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('occasion','occasion',p_occasion,p_occasion::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions WHERE aggregate_type='occasion' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_occasion::text FOR UPDATE;
  IF p_expected_version IS NOT NULL AND p_expected_version IS DISTINCT FROM v_version THEN
   RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',v_version,'game',v_before->'game'));
  END IF;
  v_result:=public.game_update_settings_internal_v1(p_occasion,p_start,p_end);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      400,v_result); END IF;
  SELECT o.data INTO v_after FROM public.occasions o WHERE o.id=p_occasion;
  v_result:=v_result||jsonb_build_object('version',v_version,'game',v_after->'game');
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'unchanged',200,v_result); END IF;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('occasion','occasion',p_occasion,p_occasion::text,1)
  ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
  SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
  v_result:=v_result||jsonb_build_object('version',v_version+1);
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'occasion.game.settings','configuration',jsonb_build_array(jsonb_build_object(
      'entityType','game_settings','entityId',p_occasion,'operation','update',
      'safeLabel','Game settings','changedFields',jsonb_build_array('data.game'))),
    ARRAY['occasion_config'],'[]','[]',v_result);
END; $function$
;
REVOKE ALL ON FUNCTION public.save_game_settings_command_internal_v1(bigint,timestamptz,timestamptz,uuid,bigint) FROM PUBLIC,anon,authenticated,service_role;
-- Released four-argument facade delegates to the same receipt owner.
CREATE OR REPLACE FUNCTION public.game_update_settings_client_sync_v1(p_occasion bigint,p_start timestamptz,p_end timestamptz,p_command_id uuid)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT public.save_game_settings_command_internal_v1(p_occasion,p_start,p_end,p_command_id,NULL);
$$;
REVOKE ALL ON FUNCTION public.game_update_settings_client_sync_v1(bigint,timestamptz,timestamptz,uuid) FROM PUBLIC,anon;
